// Self-contained review simulator. Never requests a website or changes merchant data.
window.WebsiteImportPreview=(()=>{
 const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const button=(title,action,extra='')=>`<button type="button" class="button" data-wi="${action}" ${extra}>${title}</button>`;
 let tab='import',stage='input',mode='ready',outcome='success',url='https://example.test',ack=false,extractAck=false,blocked=false,committed=false,error='',revision=1;
 let choices={products:'skip',pages:'skip',faqs:'skip',contact:false};
 const labels={products:'المنتجات',pages:'الصفحات',faqs:'الأسئلة'};
 const rows={products:[{name:'علبة قهوة جديدة',price:0,currency:'SAR',description:'سعر توضيحي يحتاج مراجعة؛ الصفر ليس ضمانًا بأن المنتج مجاني.'}],pages:[{title:'سياسة الاسترجاع',url:'https://example.test/returns',content:'نص المصدر التوضيحي كاملًا: يمكن مراجعة طلب الاسترجاع خلال أربعة عشر يومًا وفق حالة المنتج.'}],faqs:[{question:'متى يصل الطلب؟',answer:'المدة المذكورة مثال توضيحي يحتاج اعتماد التاجر.'}]};
 const old={products:[{name:'قهوة نواة',price:45,currency:'SAR'}],pages:[{title:'سياسة قديمة',url:'https://example.test/returns',content:'النص السابق المحفوظ.'}],faqs:[]};
 const chosen=()=>choices.contact||Object.values(choices).some(v=>v==='merge'||v==='replace');
 const disabled=()=>!['ready','empty'].includes(mode)||blocked;
 const records=list=>list.length?list.map(r=>`<article class="panel panel-pad">${Object.values(r).map(v=>`<p>${e(v)}</p>`).join('')}<details><summary>كل الحقول المحفوظة</summary><pre dir="ltr" style="white-space:pre-wrap;overflow-wrap:anywhere">${e(JSON.stringify(r,null,2))}</pre></details></article>`).join(''):'<p>لا توجد بيانات في هذه المجموعة.</p>';
 function render(page){
  const tabs=`<div class="wr-actions" aria-label="مساحات تحليل الموقع">${button('الاستيراد','tab-import')}${button('التقارير','tab-reports')}<a class="button" href="#/page/merchant/sari-brain">الصفحات والأسئلة</a></div>`;
  if(tab==='reports')return tabs+window.WebsiteReportsPreview.render(page);
  return tabs+`<section class="form-stack wr-workspace"><div><h2>مراجعة استيراد الموقع</h2><p>عاين البيانات، اختر ما يتغير، ثم احفظ مرة واحدة. محاكاة محلية دون اتصال بالموقع أو بالخادم.</p></div><div class="wr-controls"><label>حالة المعاينة<select id="wi-mode">${['ready','readonly','loading','error','empty'].map((v,i)=>`<option value="${v}" ${mode===v?'selected':''}>${['جاهز','قراءة فقط','تحميل','فشل القراءة','استخراج فارغ'][i]}</option>`).join('')}</select></label><label>نتيجة الاعتماد<select id="wi-outcome">${['success','conflict','uncertain'].map((v,i)=>`<option value="${v}" ${outcome===v?'selected':''}>${['نجاح','تغير البيانات','انقطاع بعد الحفظ'][i]}</option>`).join('')}</select></label></div>
   ${error?`<p role="alert">${e(error)}</p>`:''}${mode==='loading'?'<p role="status">جارٍ قراءة المعاينة…</p>':mode==='error'?'<p role="alert">تعذر تحميل المعاينة. لا يعني ذلك أن بيانات المتجر فارغة.</p>':mode==='readonly'?'<p>للقراءة فقط: يلزم إذن إعدادات المساعد للاعتماد.</p>':''}
   ${stage==='input'?`<form class="form-stack" data-wi-prepare><p>المعاينة لا تغيّر الكتالوج أو المعرفة الفعالة. HTTPS عام دون تشغيل سكربتات الصفحة. إذا تعذرت قراءة الموقع، يمكن رفع محتواه كملف معرفة.</p><label>رابط الموقع العام<input id="wi-url" type="url" value="${e(url)}" required maxlength="500" dir="ltr"></label><label class="check-label"><input id="wi-extract-ack" type="checkbox" ${extractAck?'checked':''}><span>أوافق على إعداد المعاينة التوضيحية.</span></label><button class="button primary" type="submit" ${!extractAck||disabled()?'disabled':''}>إعداد المعاينة</button></form>`:stage==='saved'?`<div class="summary-box" role="status"><h3>حُفظ الاستيراد التوضيحي</h3><p>إيصال واحد؛ قراءة النتيجة أو تكرارها لا يضيف سجلات جديدة.</p>${button('قراءة النتيجة المحفوظة','read')}${button('معاينة جديدة','reset')}</div>`:`<div class="form-stack"><p>نسخة المقارنة: ${revision}</p><p>الاستبدال يحدّث المطابق ويؤرشف بقية المجموعة. تبقى المخزونات والخيارات وتُوقف الأقسام المشتقة المرتبطة. الإضافة تحفظ الموجود. الاستخراج الفارغ لا يمسح البيانات.</p>${mode==='empty'?'<p>لم يعثر المثال على بيانات قابلة للاستخراج.</p>':''}${Object.entries(labels).map(([kind,label])=>`<section class="panel panel-pad form-stack"><h3>${label}</h3><label>قرار ${label}<select data-wi-choice="${kind}" ${disabled()?'disabled':''}>${['skip','merge','replace'].map((v,i)=>`<option value="${v}" ${choices[kind]===v?'selected':''}>${['إبقاء البيانات الحالية','إضافة الجديد فقط','استبدال هذه المجموعة'][i]}</option>`).join('')}</select></label><div class="wr-grid"><div><h4>المحفوظ حاليًا</h4>${records(old[kind])}</div><div><h4>مقترح الاستخراج</h4>${records(mode==='empty'?[]:rows[kind])}</div></div></section>`).join('')}<section class="panel panel-pad"><h3>معلومات التواصل</h3><p>الهاتف الحالي: 5550000 · المقترح: 5550001. العنوان المقترح: عنوان توضيحي. البريد وواتساب لا يُطبّقان هنا.</p><label class="check-label"><input id="wi-contact" type="checkbox" ${choices.contact?'checked':''} ${disabled()?'disabled':''}><span>تحديث الهاتف والعنوان</span></label></section><details><summary>أقسام المعرفة المرتبطة وخيارات المنتجات</summary><p>قسم مشتق من السياسة السابقة. يُوقف عند استبدال مجموعة الصفحات؛ يبقى نصه للمراجعة.</p></details><label class="check-label"><input id="wi-ack" type="checkbox" ${ack?'checked':''} ${disabled()?'disabled':''}><span>راجعت المحتوى والأسعار وأثر اختياراتي.</span></label><div class="wr-actions">${button('اعتماد الاستيراد المراجع','apply',!ack||!chosen()||disabled()?'disabled':'')}${button('تحديث المراجعة','refresh',!['ready','empty'].includes(mode)?'disabled':'')}${button('قراءة النتيجة المحفوظة','read')}${button('معاينة جديدة','reset')}</div></div>`}</section>`;
 }
 function sync(){const el=document.querySelector('[data-wi=apply]');if(el)el.disabled=!ack||!chosen()||disabled();const prepare=document.querySelector('[data-wi-prepare] button[type=submit]');if(prepare)prepare.disabled=!extractAck||disabled();}
 document.addEventListener('change',event=>{const el=event.target;if(el.id==='wi-mode'){mode=el.value;ack=false;window.render();return;}if(el.id==='wi-outcome'){outcome=el.value;return;}if(el.id==='wi-extract-ack')extractAck=el.checked;if(el.id==='wi-ack')ack=el.checked;if(el.id==='wi-url')url=el.value;if(el.id==='wi-contact'){choices.contact=el.checked;ack=false;}if(el.dataset.wiChoice){choices[el.dataset.wiChoice]=el.value;ack=false;}const checkbox=document.getElementById('wi-ack');if(checkbox)checkbox.checked=ack;sync();});
 document.addEventListener('submit',event=>{if(!event.target.matches('[data-wi-prepare]'))return;event.preventDefault();if(!extractAck||disabled())return;url=document.getElementById('wi-url').value;try{if(new URL(url).protocol!=='https:')throw Error();}catch{error='أدخل رابط HTTPS صالحًا.';window.render();return;}stage='review';extractAck=false;error='';window.render();});
 document.addEventListener('click',event=>{const el=event.target.closest('[data-wi]');if(!el||el.disabled)return;const action=el.dataset.wi;if(action.startsWith('tab-')){tab=action.slice(4);window.render();return;}if(action==='reset'){stage='input';ack=false;extractAck=false;blocked=false;committed=false;error='';choices={products:'skip',pages:'skip',faqs:'skip',contact:false};}else if(action==='refresh'){ack=false;blocked=false;error='';revision++;if(committed)stage='saved';}else if(action==='read'){ack=false;blocked=false;error='';if(committed)stage='saved';}else if(action==='apply'){if(disabled()||!ack||!chosen())return;ack=false;if(outcome==='conflict'){blocked=true;error='تغيرت البيانات. حدّث المراجعة ثم وافق من جديد.';}else if(outcome==='uncertain'){committed=true;blocked=true;error='تعذر تأكيد النتيجة. اقرأ الإيصال المحفوظ قبل أي إعادة.';}else{committed=true;stage='saved';error='';}}window.render();});
 return {handles:p=>p.route==='/merchant/smart-analysis',render,primary:()=>{if(tab==='reports')window.WebsiteReportsPreview.primary();else document.getElementById('wi-url')?.focus();},primaryLabel:()=>tab==='reports'?'تحليل وتحديث المعرفة':'مراجعة الاستيراد'};
})();
